#
# cidrly Network Configuration
# Plan: Branch Office Example
# Generated: <timestamp>
# Base IP: 192.168.10.0
# Supernet: 192.168.10.0/24
#

vlans {
    Office_Workstations {
        vlan-id 10;
        l3-interface irb.10;
    }
    VoIP_Phones {
        vlan-id 20;
        l3-interface irb.20;
    }
    Guest_WiFi {
        vlan-id 30;
        l3-interface irb.30;
    }
    Printers {
        vlan-id 40;
        l3-interface irb.40;
    }
    Servers {
        vlan-id 50;
        l3-interface irb.50;
    }
}

interfaces {
    irb {
        unit 10 {
            description "Office Workstations - 25 devices";
            family inet {
                address 192.168.10.1/26;
            }
        }
        unit 20 {
            description "VoIP Phones - 15 devices";
            family inet {
                address 192.168.10.65/27;
            }
        }
        unit 30 {
            description "Guest WiFi - 10 devices";
            family inet {
                address 192.168.10.97/27;
            }
        }
        unit 40 {
            description "Printers - 5 devices";
            family inet {
                address 192.168.10.129/28;
            }
        }
        unit 50 {
            description "Servers - 3 devices";
            family inet {
                address 192.168.10.145/29;
            }
